 "content": "def transform(grid):
    out = [row[:] for row in grid]
    marker = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 3 and 2 < r < 10 and 3 < c < 11]
    if len(marker) != 1:
        return out
    mr, mc = marker[0]
    for r in range(3, 10):
        for c in range(4, 11):
            d = max(abs(r - mr), abs(c - mc))
            if d == 0:
                out[r][c] = 3
            else:
                out[r][c] = 4 if d % 2 == 1 else 2
    return out
